--[[
	MenuArt — รูปปุ่มเมนูซ้ายในล็อบบี้ (สร้างโดย tools/menu_art.py — อย่าแก้มือ)
	MenuArt.Image(name) -> EditableImage (แคชไว้) · MenuArt.Size[name] = Vector2 ขนาดรูป
]]

local AssetService = game:GetService("AssetService")

local MenuArt = { Size = {} }
local DATA = {
	Classes = "",
	-- Classes: 300x101
	Quests = "",
	-- Quests: 300x96
	Badges = "",
	-- Badges: 300x94
	Shop = "",
	-- Shop: 300x92
	Settings = "",
	-- Settings: 300x105
}

local B64 = {}
for i, c in ipairs(string.split("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", "")) do
	B64[string.byte(c)] = i - 1
end

local function b64decode(s)
	local n = #s
	local pad = (s:sub(-2) == "==") and 2 or ((s:sub(-1) == "=") and 1 or 0)
	local buf = buffer.create(n // 4 * 3 - pad)
	local o = 0
	for i = 1, n, 4 do
		local a, b, c, d = s:byte(i, i + 3)
		local t = B64[a] * 262144 + B64[b] * 4096 + (B64[c] or 0) * 64 + (B64[d] or 0)
		if o < buffer.len(buf) then buffer.writeu8(buf, o, t // 65536) end
		if o + 1 < buffer.len(buf) then buffer.writeu8(buf, o + 1, (t // 256) % 256) end
		if o + 2 < buffer.len(buf) then buffer.writeu8(buf, o + 2, t % 256) end
		o += 3
	end
	return buf
end

local cache = {}
function MenuArt.Image(name)
	if cache[name] ~= nil then
		return cache[name] or nil
	end
	cache[name] = false
	local str = DATA[name]
	if not str then
		return nil
	end
	local src = b64decode(str)
	local w, h, np = buffer.readu16(src, 0), buffer.readu16(src, 2), buffer.readu8(src, 4)
	local out = buffer.create(w * h * 4)
	local off, o = 5 + np * 4, 0
	local len = buffer.len(src)
	while off < len do
		local count, idx = buffer.readu8(src, off), buffer.readu8(src, off + 1)
		local p = 5 + idx * 4
		local px = buffer.readu32(src, p)
		for _ = 1, count do
			buffer.writeu32(out, o, px)
			o += 4
		end
		off += 2
	end
	local ok, img = pcall(function()
		return AssetService:CreateEditableImage({ Size = Vector2.new(w, h) })
	end)
	if not ok or not img then
		return nil
	end
	img:WritePixelsBuffer(Vector2.zero, Vector2.new(w, h), out)
	cache[name] = img
	MenuArt.Size[name] = Vector2.new(w, h)
	return img
end

return MenuArt
